\label{t:C1_wellposed}
Let $k\geq 1$, $\gamma \in (-3,0]$, $s\in (0,1/2)$, $m_1 > 3 + \gamma + 2s$, and $m_0$ be sufficiently large depending only on $k$, $\gamma$, $s$, and $m_1$.  Let the initial data $0\leq f_{\rm in}\in \tilde X^{k,m_0,m_1}$.                                                                                     
Then there exists a time $T>0$, depending only on $\|f_{\rm in}\|_{\tilde X^{k,m_0,m_1}}$, $\gamma$, $s$, $m_0$, $m_1$, and $\tilde b$, and a unique solution $f\geq 0$ of~\eqref{e:Boltzmann} such that
\[
	\begin{split}
		&f \in \tilde Y_T^{k,m_0,m_1}
			\cap C([0,T]; C^k(\mathbb T^3\times \mathbb R^3))
			\cap C^1([0,T]; C^{k-1}(\mathbb T^3\times \mathbb R^3))
		\\&
		\text{and }
		\|f\|_{\tilde Y_T^{k,m_0,m_1}}
			\lesssim \|f_{\rm in}\|_{\tilde X^{k,m_0,m_1}}.
	\end{split}
\]

\label{p:non-singular}
	Suppose that $f,g : \mathbb T^3 \times \mathbb R^3 \to \mathbb R$. Then, for any $\epsilon>0$ and $n\geq 0$,
	\[
	\begin{split}
	\| Q_{\rm ns} (g,f) \|_{L^{2,n}}
	&\lesssim
	\begin{cases}
	\|g\|_{L^{\infty,3+\gamma+\epsilon}} \|f\|_{L^{2,n}}\\
	\|g\|_{L^{2,n}} \|f\|_{L^{\infty,n + \epsilon + 3/2 +\gamma + (3/2-n)_+}}.
	\end{cases}
	\end{split}
	\]

\label{interpolation lemma}

	If $n,m \geq 0$, $k' \in (0,k)$, and $l<(m-\frac32)(1-\frac{k'}{k})+n\frac{k'}{k}$, then
	\[
		\|f\|_{H^{k',l}}
	\lesssim
	\|f\|_{L^{\infty, m}}^{1-\frac{k'}{k}}
	\|f\|_{H^{k, n}}^{\frac{k'}{k}}
	.
	\]

\label{p:commutator}
	For any $\epsilon>0$, $\gamma \in (-3,0]$,                                                     
	$\mu \in ((1-2s)_+, 2-2s)$, $m > \max\{3+\gamma+2s, \ell + \gamma + \frac{3}{2}\}$, $\ell > \frac{3}{2}$, and $f,g : \mathbb R^3\to\mathbb R$, we have
		\begin{align*}

		\| \langle v\rangle^\ell Q_{\rm s}(g,f) - Q_{\rm s}(g, \langle v\rangle^\ell f)\|_{L^2}
		\lesssim
			(\|f\|_{L^{2,\ell+3/2+\epsilon}} + \|f\|_{H^{2s -1 + \mu,\mu+\ell+\gamma + 2s}})
				\|g\|_{L^{\infty, m}}.
		\end{align*}

\label{p:thm_2.4}
	For any $f,g : \mathbb R^3 \to \mathbb R$, $\gamma \in (-3,0]$, $\gamma + 2s \leq 0$, and $\epsilon>0$:
	\begin{enumerate}[(i)]








		\item If                          
			$\theta \in (0, 2s)$, then
		\[
			\int Q_{\rm s}(g,f) h dv
				\lesssim \|g\|_{L^{\infty,3+\gamma+2s+\epsilon}}
					\|f\|_{H^{2s-\theta}}
					\|h\|_{H^{\theta}}.
		\]
		\item If $\theta > 0$, then
		\[
			\|Q_{\rm s}(g,f)\|_{L^2}
				\lesssim \|g\|_{L^{\infty,3+\gamma+2s+\epsilon}}
						\|f\|_{H^{2s+\theta}}.
		\]
		\item If $n>3/2+\gamma+2s$, $m>3/2+\gamma+(3/2-n)_{+}$, and $\alpha>2s$, then
			\[
			\|Q_{\rm s}(g,f)\|_{L^{2,n}}
				\lesssim
				\|g\|_{L^{2,n}}
				\left(
					\|f\|_{L^{\infty, m}}
					+\|\langle v\rangle^{n+5/2+ (3/2-n)_+ + \alpha+\gamma+\epsilon}f\|_{C^{\alpha}_{v}}
				\right).
			\]
			\item If $n\geq 0$ and $m > n + 6 + \gamma + 2s$, we have
			\[
			\int \langle v\rangle^{2n}fQ_{\rm s}(g,f)\,dv
			\lesssim
			\|g\|_{L^{\infty,m}}
			\|f\|_{L^{2,n}}^{2} 
			.
			\]
	\end{enumerate}

\label{p:symmetry}  
	Suppose that $f,g : \mathbb T^3 \times \mathbb R^3 \to \mathbb R$. If $\gamma \in (-3,0]$, $\epsilon>0$, $\mu \in ((1-2s)_+,2-2s)$, $\kappa\in(s, \min\{2s,1\})$, $n>\frac{3}{2}$, and $m > \max\{3+\gamma+2s, n + \gamma + \frac{3}{2}\}$. Then
	\[
	\begin{split}
	\Big|\int &\langle v\rangle^{2n} Q_{\rm s} (g,f) \partial f dv dx \Big|
	\lesssim
	\|g\|_{L^{\infty, m}}
	\left(
	\|f\|_{L^{2,n + 3/2 + \epsilon}}
	+
	\|f\|_{H^{2s - 1 + \mu,\mu+n +\gamma + 2s}}
	\right)
	\|f\|_{H^{1,n}}


	\\&+
	\|\partial g\|_{H^{3/2 + (2s-1/2)_+ + \epsilon,3+\gamma + 2s + \epsilon}} \|f\|_{H^{1,n}}^2
		+
	\| g\|_{C^{\kappa, 3+\epsilon}}
	\|f\|_{H^{s,n + 3/2 + \epsilon + (\gamma + 2s + 1)_+}}
	\|f\|_{H^{1, n}}
	,
	\end{split}
	\]
	where $\partial = \partial_{x_i}$ or $\partial_{v_i}$ for some $i \in \{1,2,3\}$.

\label{p:existence}
			Suppose that $T>0, k\geq 5, n>3/2+(\gamma+2s)_{+}, \sigma \in [0,1], \epsilon, \delta\geq0$, and $m\geq 0$. Suppose that $R,f \in Y_{T}^{k,n,m}$
			\begin{equation}\label{e.w316}
			\begin{cases}
			\mathcal L_{\sigma, \epsilon, \delta}f 
			=R
			, \qquad &\text{in}~(0,T)\times \mathbb{T}^{3}\times \mathbb{R}^{3}
			\\f(0,\cdot, \cdot)
			=f_{\text{in}}, \qquad &\text{in}~ \mathbb{T}^{3}\times \mathbb{R}^{3}.
			\end{cases}
			\end{equation}
			 For any $\mu>0$, if $\delta=0$ and $m\geq 3/2+\mu$ or if $\delta>0$, then
			\begin{equation}\label{e:w05081}
			\begin{split}
			\|f\|_{L^{\infty, m}}
			&\leq
			\exp\Big\{C\int_{0}^{T} \|g(t)\|_{L^{\infty, \max\{m,3/2+\mu\}}}dt\Big\}
			\Big(\|f_{\rm in}\|_{L^{\infty, m}}
			+
			\int_{0}^{T} \|R(t)\|_{L^{\infty, m}}dt
			\Big)
			.
			\end{split}
			\end{equation}
			If $\delta=0$ and $m$ is sufficiently large depending on $k,n,\gamma$, and $s$, then
			\begin{equation}\label{e:w05082}
			\begin{split}
			\|f\|_{L^{\infty, m}([0,T];H_{x,v}^{k,n})}
			&\leq
			\exp\Big\{C\int_{0}^{T} \|g(t)\|_{X_{x,v}^{k,n,m}}\,dt\Big\}

			\Big((1+T)\|f_{\rm in}\|_{X_{x,v}^{k,n,m}}
			+
			\int_{0}^{T} \|R(t)\|_{X_{x,v}^{k,n,m}}dt
			\Big)
			.
			\end{split}
			\end{equation}

The argument of \eqref{e:w05081} goes exactly as that in \cite[Proposition 3.1]{HST_boltz_wp} and hence we omit the proof here. Now we focus on proving \eqref{e:w05082}. First,  we let $\alpha, \beta \in \mathbb{N}_{0}^3$ be any multi-indices such that $|\alpha|+|\beta|=k$. Then, differentiating \cref{e.w451}, multiplying the resulting equation by $\langle v\rangle^{2n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f$, integrating in $x$ and $v$, we get
	\[
	\begin{split}
	\frac{1}{2}\frac{d}{dt}\int |\langle v\rangle^{n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f|^{2}\,dxdv
	&=
	-\sigma \int \left(\sum_{i=1}^{3}\beta_{i}\partial_{x_i}\partial_{x}^{\alpha}\partial_{v}^{\beta-e_{i}}f \right)\langle v\rangle^{2n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f\,dxdv
	\\&\quad+
	\sigma \sum_{\substack{\alpha'+\alpha''=\alpha \\ \beta'+\beta''=\beta}} C_{\alpha',\beta',\alpha'',\beta''} \int Q(\partial_{x}^{\alpha'}\partial_{v}^{\beta'}g,\partial_{x}^{\alpha'}\partial_{v}^{\beta'}f)\langle v\rangle^{2n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f\,dxdv
	\\&\quad-
	(\epsilon + 1-\sigma)\int |\nabla_{x,v}\partial_{x}^{\alpha}\partial_{v}^{\beta}f|^{2}
	+
	\int \partial_{x}^{\alpha}\partial_{v}^{\beta}R\langle v\rangle^{2n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f\,dxdv
	\\&=
	I_{1}+I_{2}+I_{3}+I_{4},
	\end{split}
	\]
	for some constants $C_{\alpha',\beta',\alpha'',\beta''}>0$ depending only on the subscripted quantities.

	We see that $I_{1}$ is bounded by $\|f\|_{H^{k,n}}^2$, $I_{4}$ is bounded by  $                               

	\|R\|_{H^{k,n}}^{2}+\|f\|_{H^{k,n}}^{2}$, and $I_{3}$ has a good sign. Thus, our focus is primarily on $I_{2}$, the term involving the collision operator $Q$. We argue case by case depending on the size of $|\alpha''| + |\beta''|$ in order to establish that	\begin{equation}\label{e.w05091}
	\begin{split}
	I_{2}
	\lesssim			
	\|g\|_{X^{k,n,m}}
	\|f\|_{X^{k,n,m}}^{2}
	.
	\end{split}
	\end{equation}
	The proof of~\eqref{e.w05091} is postponed momentarily while we show how to conclude.  Indeed,



	assuming \eqref{e.w05091} is proved, we arrive at
	\begin{equation}
	\begin{split}
		\frac{1}{2}\frac{d}{dt}\int |\langle v\rangle^{n}\partial_{x}^{\alpha}\partial_{v}^{\beta}f|^{2}\,dxdv
		&\lesssim
		(\|g\|_{X^{k,n,m}}+1)\|f\|_{X^{k,n,m}}^{2}
		+
		\|R\|_{H^{k,n}}^{2}
		.
	\end{split}
	\end{equation}
	Recalling the definition of $X^{k,n,m}$ in~\eqref{d:X space} and using~\eqref{e:w05081}, we find
	\begin{equation}
	\begin{split}
	\frac{1}{2}\frac{d}{dt}\|f\|_{H^{k,n}}^{2}
	&\lesssim
		(\|g(t)\|_{X^{k,n,m}}+1)
			\|f\|_{H^{k,n}}^{2}\\
		&\quad +(\|g(t)\|_{X^{k,n,m}}+1)
			\exp\left\{C\int_0^T\|g(t)\|_{X^{k,n,m}} dt\right\}
			\left(\|f_{\rm in}\|_{L^{\infty, m}}^2
			+ \|R\|_{X^{k,n,m}}^2\right)
		.
	\end{split}
	\end{equation}
	Therefore, we conclude the proof of equation \eqref{e:w05082} by applying Gr\"onwall inequality.                                  

	We now establish \eqref{e.w05091}.	For notational ease, we set
	\begin{align}
	F=\partial^{\alpha''}_{x}\partial^{\beta''}_{v}f
	 {\rm ,\qquad{}} 
	G=\partial^{\alpha'}_{x}\partial^{\beta'}_{v}g
	.
	\end{align}
	Thus, we are estimating terms of the form
	\begin{equation}\label{e.Weinans_decomposition}
		\begin{split}
		\int \langle v\rangle^{2n} &Q(G,F) \partial^{\alpha'}_x \partial_v^{\beta'} F dv dx\\
			&= \int \langle v\rangle^{2n} Q_{\rm s}(G,F) \partial^{\alpha'}_x \partial_v^{\beta'} F dv dx
				+ \int \langle v\rangle^{2n} Q_{\rm ns}(G,F) \partial^{\alpha'}_x \partial_v^{\beta'} F dv dx.
		\end{split}
	\end{equation}









	\smallskip

	\textbf{Case one:  $|\alpha''|+|\beta''|= k$, i.e., $\alpha''=\alpha$, $\beta''=\beta$, and in the form of $\int \langle v\rangle^{2n}Q(g,F)F$.}\\
	We estimate the $Q_{\rm s}$ term first. We proceed by using \Cref{p:thm_2.4}.(iv), up to increasing $m$ if necessary,
	\[
	\begin{split}
	\int \langle v\rangle^{2n}Q_{\rm s}(g,F)F\,dvdx
	&\lesssim
	\int
	\|F\|_{L_{v}^{2,n}}^{2} 
	\|g\|_{L_{v}^{\infty,m}}
	\,dx
	\lesssim
	\|F\|_{L^{2,n}}^{2} 
	\|g\|_{L^{\infty,m}}\\
	&\lesssim
	\|f\|_{H^{k,n}}^{2}
	\|g\|_{L^{\infty,m}}
	\lesssim
	\|f\|_{X^{k,n,m}}^{2}
	\|g\|_{X^{k,n,m}}
	,
	\end{split}
	\]
	as desired.



	Furthermore, for $\int \langle v\rangle^{2n}Q_{\rm ns}(g,F)F\,dvdx$, we recall~\eqref{e.carleman1} and apply \Cref{p:non-singular} to find 
	\[
	\begin{split}
	\int \langle v\rangle^{2n}Q_{\rm ns}(g,F)F\,dvdx
	&\approx
	\int \langle v\rangle^{2n} (S_\gamma *g) F^2 dv dx


	\lesssim
		\int \|g\|_{L_{v}^{\infty,n}} \|F\|_{L_{v}^{2,n}}^2\,dx
	\\&\lesssim
		\|g\|_{L^{\infty,m}} \|F\|_{L^{2,n}}
	\lesssim
		\|g\|_{L^{\infty,m}} \|f\|_{H^{k,n}}^2
	\leq
		\|g\|_{X^{k,n,m}}
		\|f\|_{X^{k,n,m}}^2
	.
	\end{split}
	\]

















	This concludes the proof of \eqref{e.w05091} in case one.



	\smallskip

	\textbf{Case two:  $|\alpha''|+|\beta''|= k-1$, and in the form, $\int \langle v\rangle^{2n}Q(\partial g,F)\partial F$.} Here we denote derivative operator $\partial=\partial_x^{\alpha'}\partial_v^{\beta'}$ as  $|\alpha'|+|\beta'|=1$.  

	We first estimate the $Q_{\rm s}$ portion.  Fix $\epsilon \in (0,\min\{s,1-s\})$.  Let $\mu = (1-2s)_+ + \epsilon$, $\kappa = s + \epsilon$, and $\tilde m = \epsilon + \max\{3+\gamma + 2s, n + \gamma + 3/2\}$.  We then directly apply \Cref{p:symmetry} to find
	\[
	\begin{split}
		\left|\int \langle v\rangle^{2n} Q_{\rm s} (\partial g,F) \partial F dv dx \right|
		&\lesssim
			\|\partial g\|_{L^{\infty, \tilde m}}
			\|F\|_{H^{2s -1 + \mu,\mu+n + 3/2}}
			\|F\|_{H^{1,n}}\\
			&\quad+ 
			\|\partial^{2} g\|_{H^{3-s,3+\epsilon}} \|F\|_{H^{1,n}}^2
			+
			\|\partial g\|_{C^{\kappa, 3+\epsilon}}
			\|F\|_{H^{s, n + 5/2 + \epsilon}}
			\|F\|_{H^{1, n}}\\
			&\lesssim 
			\|\partial g\|_{L^{\infty, \tilde m}}
			\|f\|_{H^{k- 2(1-s) + \mu,\mu+n + 3/2}}
			\|f\|_{H^{k,n}}\\
			&\quad+ 
			\|\partial^{2} g\|_{H^{3-s,3+\epsilon}} \|f\|_{H^{k,n}}^2
			+
			\|\partial g\|_{C^{\kappa, 3+\epsilon}}
			\|f\|_{H^{k-(1-s), n + 5/2 + \epsilon}}
			\|f\|_{H^{k, n}}
			.
		\end{split}
	\]
	Applying the Sobolev embedding theorem on terms involving $g$ and then  \Cref{interpolation lemma} (up to increasing $m$ if necessary) yields
	\[
	\begin{split}
	\left|\int \langle v\rangle^{2n} Q_{\rm s} (\partial g,F) \partial F dv dx \right|
	&\lesssim
	\| g\|_{H^{4+\epsilon, \tilde m}}
	\|f\|_{H^{k- (2-2s) + \mu,\mu+n + 3/2}}
	\|f\|_{H^{k,n}}
	+
	\| g\|_{H^{5-s,3+\epsilon}} \|f\|_{H^{k,n}}^2
	\\&\quad
	+
	\| g\|_{H^{4+\kappa, 3+\epsilon}}
	\|f\|_{H^{k-(1-s),n + 5/2 + \epsilon}}
	\|f\|_{H^{k, n}}
	\lesssim
	\|g\|_{X^{k,n,m}}
	\|f\|_{X^{k,n,m}}^{2}
	.
	\end{split}
	\]
	The estimate of the non-singular part $Q_{{\rm ns}}$ is the same as in the previous case and is thus omitted.






























	\smallskip

	\textbf{Case three:  $|\alpha''|+|\beta''|= k-2$ and $|\alpha'|+|\beta'|=2$.}





	First, we estimate the $Q_{\rm s}$ term.  We see
	\begin{equation}\label{e.c571}
	\begin{split}
	\int \langle v\rangle^{2n} &Q_{\rm s}(G,F)\partial^\alpha_x \partial^\beta_v f\,dvdx

		\leq \|Q_{\rm s}(G,F)\|_{L^{2,n}} \|f\|_{H^{k,n}}\\
		&\leq \left(\|Q_{\rm s}(G,\langle v\rangle^n F) - \langle v\rangle^n Q_{\rm s}(G,F)\|_{L^2} + \|Q_{\rm s}(G,\langle v\rangle^n F)\|_{L^2} \right)\|f\|_{H^{k,n}}\\
		&=: (B_1 + B_2)\|f\|_{H^{k,n}}.
	\end{split}
	\end{equation}




























	We estimate $B_2$ first.  Fix any $\theta \in (0,\min\{\frac{2-2s}{3}, \frac{3}{4}\})$ and let $p = 3/(4\theta)$ and $q = \frac{3}{3-4\theta}$.                                                        
	Then we apply \Cref{p:thm_2.4}.(ii), H\"older's inequality,  and the Sobolev embedding theorem to find                                                                                                                                                        
	\[
	\begin{split}
	B_{2}
	&\lesssim
	\Big(
	\int \|G\|_{L^{\infty,3}_{v}}^{2}
	\|F\|_{H^{2s+\theta,n}_{v}}^{2}
	\,dx\Big)^{1/2}
	\lesssim
	\|G\|_{L_{x}^{2p}L^{\infty,3}_{v}}
	\|F\|_{L_{x}^{2q}H^{2s+\theta,n}_{v}}
	\\&\lesssim
	\|G\|_{H_{x}^{3/2-2\theta}H^{3/2+\theta,3}_{v}}
	\|F\|_{H_{x}^{2\theta}H^{2s+\theta,n}_{v}}
	\lesssim
	\|G\|_{H^{3-\theta,3}}
	\|F\|_{H^{2s+3\theta,n}}
	\lesssim
	\|g\|_{X^{k,n,m}}
	\|f\|_{X^{k,n,m}}
	.
	\end{split}
	\]
	The last inequality follows by our choice of $\theta$.

	For $B_{1}$, for any $\mu\in ((1-2s)_+, 2-2s)$ and $\tilde m = 1 + \max\{3, n+ \gamma + 3/2\}$, we appeal to our commutator estimate \Cref{p:commutator}, the Cauchy-Schwarz inequality, and the Sobolev embedding theorem to obtain: 
	\[
	\begin{split}
	&B_{1}




	\lesssim
		\left(
		\int (\|F\|_{L_{v}^{2,n+2}} + \|F\|_{H_{v}^{2s -1 + \mu,\mu+n}})^{2}
		\|G\|_{L_{v}^{\infty, \tilde m}}^{2}\,dx\right)^{1/2}









	\\&\lesssim
		\|G\|_{L_{x}^{4}L_{v}^{\infty, \tilde m}} \left(\|F\|_{L_{x}^{4}L_{v}^{2,n+2}}
		+
		\|F\|_{L_{x}^{4}H_{v}^{2s -1 + \mu,\mu+n}}\right)
	\lesssim
		\|G\|_{H^{5/2, \tilde m}} \left(\|F\|_{H^{3/4, n+2}}
		+
		\|F\|_{H_{v}^{2s - 1/4 + \mu,\mu+n}}\right)





	\\&\lesssim
		\|g\|_{H^{9/2, \tilde m}}
		(\|f\|_{H^{k- 5/4,n+2}}
		+
		\|f\|_{H^{k +  2s - 9/4 + \mu,\mu+n}}
		)
	.
	\end{split}
	\]
	Notice that $2s - 9/4 + \mu < 0$ as $\mu < 2-2s$.  With this, observe that all three norms above involve regularity of order strictly less than $k$.  Hence, assuming $m$ is sufficiently large, the interpolation lemma \Cref{interpolation lemma} yields
	\[
	\begin{split}
	B_{1}
 	\lesssim
	\|g\|_{X^{k,n,m}}
	\|f\|_{X^{k,n,m}}
	.
	\end{split}
	\]
	This concludes the estimates for the singular part.

	For the non-singular part, we apply \Cref{p:non-singular}  to find
	\[
	\begin{split}
	&\int \langle v\rangle^{2n}Q_{\rm ns}(G,F) \partial^\alpha_x\partial^\beta_v f \,dvdx
	\lesssim
	\|f\|_{H^{k,n}}
 \|Q_{\rm ns}(G,F)\|_{L^{2,n}}
 \lesssim
 \|f\|_{H^{k,n}}
 	\|G\|_{L^{\infty,3+\gamma+\epsilon}} \|F\|_{L^{2,n }}.
	\end{split}
	\]
	Using the Sobolev embedding theorem and \Cref{interpolation lemma}, we obtain the desired estimate
	\[
		\int \langle v\rangle^{2n}Q_{\rm ns}(G,F) \partial^\alpha_x\partial^\beta_v f \,dvdx
			\lesssim \|g\|_{X^{k,n,m}} \|f\|_{X^{k,n,m}}^2.
	\]
	This concludes the proof of~\eqref{e.w05091} in this case.































	\smallskip


	\textbf{Case four:  $|\alpha''|+|\beta''|=k-3$ and $|\alpha'|+|\beta'|=3$.}
	The proof of~\eqref{e.w05091} in this case is exactly as in case three, except with the choices
	\[
		\theta \in \left(0, \min\left\{\frac{1}{2},\frac{5-4s}{6}\right\}\right),
			\quad
		p = \frac{3}{1+4\theta},
			\quad\text{and}\quad
		q = \frac{3}{2-4\theta}
	\]
	in the estimate of $Q_{\rm s}$.  As such, we omit the proof.

































































































































































	\smallskip


	\textbf{Case five:  $|\alpha''|+|\beta''|= k-4$ and $|\alpha'|+|\beta'|= 4$.} 
	We begin with the singular term:
	\[
		\begin{split}
			\int \langle v\rangle^{2n}Q_{\rm s}(G,F)\partial^{\alpha}_{x}\partial^{\beta}_{v}f\,dvdx
				&\lesssim \|\partial^{\alpha}_{x}\partial^{\beta}_{v}f\|_{L^{2,n}}
					\|Q_{\rm s}(G,F)\|_{L^{2,n}}
				\leq \|f\|_{H^{k,n}}
					\|Q_{\rm s}(G,F)\|_{L^{2,n}}.
		\end{split}
	\]
	It is clear that we need only bound the last term above.  Recalling \Cref{p:thm_2.4}.(iii), we have, for any $\mu \in ((2s-1)_+,1)$,
	\[
	\begin{split}
	\|Q_{s}(G,F)\|_{L_v^{2,n}} 
	&\lesssim
	\left( \|F\|_{L_{v}^{\infty, 3}} +\|\langle v\rangle^{n+5/2+ \mu} F\|_{C_v^{1+\mu}}
	\right)
	\|G\|_{L_{v}^{2,n}}
	.
	\end{split}
	\]
	Applying the Sobolev embedding theorem with $\tilde m$ sufficiently large (depending only on $n$), we obtain, for $\epsilon = (1-\mu)/4$, 
	\[
		\|Q_{s}(G,F)\|_{L_v^{2,n}} 
			\lesssim
			\|F\|_{H_v^{5/2 + \mu + \epsilon, \tilde m}}
			\|G\|_{L_{v}^{2,n}}.
	\]


	Using H\"older's inequality and the Sobolev embedding theorem yields
	\[
	\begin{split}
		\|Q_{\rm s}(G,F)\|_{L^{2,n}}^2
			&\lesssim	\int
				\|F\|_{H_{v}^{5/2+\mu+\epsilon,\tilde m}}^{2}
				\|G\|_{L_{v}^{2,n}}^{2}\,dx
			\leq
				\|F\|^2_{L_{x}^{3}H_{v}^{5/2+\mu+\epsilon,\tilde m}}
				\|G\|^2_{L^{6}_{x}L_{v}^{2,n}}
			\\&\lesssim
				\|F\|_{H_{x}^{1/2} H_{v}^{5/2+\mu+\epsilon, \tilde m}}^2
				\|G\|_{H^{1,n}}^2
			\leq
				\|g\|_{H^{k,n}}^2
				\|f\|_{H^{k-1 + \mu+\epsilon, \tilde m}}^2.
	\end{split}
	\]
	To control the last term, we use the interpolation lemma, \Cref{interpolation lemma} and that, by construction, $\mu + \epsilon < 1$, to find
	\[
		\|f\|_{H^{k-1 + \mu, \tilde m}}
			\lesssim \|f\|_{X^{k,n,m}}
	\]
	as long as $m$ is sufficiently large depending only on $n$ and $s$.  This concludes the proof of the bound of the singular term.

	We now consider the non-singular part.  As above, it is enough to bound $\|Q_{\rm ns}(G,F)\|_{L^{2,n}}$.  To this end, applying \Cref{p:non-singular} yields









	\[
	\begin{split}
		\|Q_{\rm ns}(G,F)\|_{L^{2,n}}^2
		&\lesssim
			\left(
			\int\|F\|_{L_v^{\infty,n+3}}^{2}
			\|G\|_{L_v^{2,n}}^{2}\,dx\right)^{1/2}
		\lesssim
			\|F\|_{L^{\infty,n+3}}^2
			\|G\|_{L^{2,n}}^2
		\leq
			\|F\|_{L^{\infty,n+3}}^2
			\|g\|_{X^{k,n,m}}^2.
	\end{split}
	\]
	Thus, we need only bound the norm of $F$ on the right hand side.  By the Sobolev embedding theorem and the interpolation lemma \Cref{interpolation lemma}, we find
	\[
		\|F\|_{L^{\infty,n+3}}
			\lesssim \|F\|_{H^{7/2 + 1/4,n+3}}
			\lesssim \|f\|_{H^{k-1/4, n+3}}
			\lesssim \|f\|_{X^{k,n,m}},
	\]
	as long as $m$ is sufficiently large.  This concludes the proof of~\eqref{e.w05091} in case five.

	\smallskip

	\textbf{Case six:  $|\alpha''|+|\beta''|\leq k-5$ and $|\alpha'|+|\beta'|\geq 5$.} 


	We begin by bounding the term with $Q_{\rm s}$.  As above, it is enough to bound $Q_{\rm s}(G,F)$ in $L^{2,n}$.  First, by \Cref{p:thm_2.4}.(iii) with $\mu \in ((2s-1)_+,1)$, we find
	\[
	\|Q_{\rm s}(G,F)\|_{L^{2,n}}^2
	\lesssim
		\int \|G\|_{L_{v}^{2,n}}^{2}
		\left(
		\|F\|_{L_{v}^{\infty, m}}^2
		+\|\langle v\rangle^{n + 5/2 + \mu} F\|_{C^{1+\mu}}^2
		\right)\,dx.
	\]
	Applying the Sobolev embedding theorem and letting $\epsilon = (1-\mu)/2$, we obtain
	\[
		\begin{split}
		\|Q_{\rm s}(G,F)\|_{L^{2,n}}^2
			&\lesssim \int \|G\|_{L_{v}^{2,n}}^{2}
				\|F\|_{H^{5/2 + \mu, \tilde m}_{v}}^2
				\,dx
			\leq \|G\|_{L^{2,n}}^2 \|F\|_{L^\infty_x H_v^{5/2 + \mu, \tilde m}}^2\\
			&\lesssim \|G\|_{L^{2,n}}^2 \|F\|_{H^{4 + \mu + \epsilon, \tilde m}}^2
			\lesssim \|g\|_{H^{k,n}}^2 \|f\|_{H^{k-1+\mu+\epsilon, \tilde m}}^2,
		\end{split}
	\]
	where $\tilde m$ is a constant depending only on $n$.  The proof concludes as in the previous case by using the fact that $k-1 + \mu + \epsilon < k$ and \Cref{interpolation lemma}.


















The estimate of the non-singular part $Q_{{\rm ns}}$ is the same as in the previous case and is thus omitted.  This concludes the proof of~\eqref{e.w05091} in case six and, thus, all cases.

Consider any two solutions $f$ and $g$ of~\eqref{e:Boltzmann} with $f(0,\cdot,\cdot)= g(0,\cdot,\cdot) = f_{\rm in}$ and set $h=f-g$.  We have
\begin{align}\label{e.w05263}
h_{t} + v\cdot \nabla_{x} h
=
Q(f,h)+Q(h,g).
\end{align}
Then, we multiply~\eqref{e.w05263} by $\langle v\rangle^{2n}h$ and integrate with respect to $v$ and $x$, yielding
\begin{equation}\label{e.w05264}
\begin{split}
	\frac{1}{2}\frac{d}{dt}\|h\|_{L^{2,n}}^2
	&=
	\int \langle v\rangle^{2n}Q(f,h)h\,dvdx
	+
	\int \langle v\rangle^{2n}Q(h,g)h\,dvdx
	=
	I_{1}+I_{2}
	,
\end{split}
\end{equation}
where
\begin{equation}
\begin{split}
	I_{1}
	&=
	\int \langle v\rangle^{2n}Q_{\rm s}(f,h)h\,dvdx
	+
	\int \langle v\rangle^{2n}Q_{\rm ns}(f,h)h\,dvdx
	=
	I_{11}+I_{12}
\end{split}
\end{equation}
and
\begin{equation}
\begin{split}
	I_{2}
	&=
	\int \langle v\rangle^{2n}Q_{\rm s}(h,g)h\,dvdx
	+
	\int \langle v\rangle^{2n}Q_{\rm ns}(h,g)h\,dvdx
	=
	I_{21}+I_{22}
	.
\end{split}
\end{equation}
For $I_{11}$, \Cref{p:thm_2.4}.(iv) yields, for $\tilde m$ sufficiently large,
\begin{equation}\label{e.c6111}
I_{11}
\lesssim
\int
\|h\|_{L_{v}^{2,n}}^{2} 
\|f\|_{L_{v}^{\infty,\tilde m}}
\,dx
\lesssim
\|h\|_{L^{2}_{x}L_{v}^{2,n}}^{2} 
\|f\|_{L^{\infty}_{x}L_{v}^{\infty,\tilde m}}
\lesssim
\|h\|_{L^{2,n}}^{2} 
\|f\|_{X^{k,n,m}}
.
\end{equation}
For $I_{12}$, we apply \Cref{p:non-singular} to obtain
\begin{equation}\label{e.c6112}
	I_{12}



		\lesssim
			\|h\|_{L^{2,n}}^{2}
			\|f\|_{L^{\infty,3+\gamma+\epsilon}} 
		\lesssim
			\|h\|_{L^{2,n}}^{2} 
			\|f\|_{X^{k,n,m}}
.
\end{equation}
For $I_{21}$, fix $\alpha \in (2s, 2)$, $\epsilon = (2 - \alpha)/2$, and $\tilde m$ be sufficiently large and apply \Cref{p:thm_2.4}.(iii) to find
\begin{equation}\label{e.c6113}
	\begin{split}
	I_{21}
		&\lesssim \int \|h\|_{L_{v}^{2,n}}^2
			\left(
			\|g\|_{L_{v}^{\infty, m}}
			+\|\langle v\rangle^{\tilde m} g\|_{C^{\alpha}_{v}}
			\right) dx
		\lesssim
			\|h\|_{L^{2,n}}^{2} 
			\|g\|_{L^{\infty}_{x}H_v^{3/2 + \alpha, \tilde m}}\\
		&\lesssim
			\|h\|_{L^{2,n}}^{2} 
			\|g\|_{H^{3 + \alpha + \epsilon, \tilde m}}
		\lesssim
			\|h\|_{L^{2,n}}^{2} 
			\|g\|_{X^{k,n,m}}.
	\end{split}
\end{equation}






























For $I_{22}$, apply \Cref{p:non-singular} to find
\begin{equation}\label{e.c6114}
	\begin{split}
		I_{22} 
			\lesssim \|h\|_{L^{2,n}}^2 \|g\|_{L^{\infty,n+3}}
			\lesssim \|h\|_{L^{2,n}}^2 \|g\|_{X^{k,n,m}}.
	\end{split}
\end{equation}




























Combining the estimates of $I_{11},I_{12},I_{21}$, and $I_{22}$, that is,~\eqref{e.c6111}-\eqref{e.c6114}, and recalling that $\|f\|_{X^{k,n,m}}, \|g\|_{X^{k,n,m}} \lesssim 1$, we find
\[
	\frac{d}{dt} \|h(t)\|_{L^{2,n}}^2
		\lesssim \|h(t)\|_{L^{2,n}}^2.
\]
The Gr\"onwall inequality and the fact that $h(0,\cdot,\cdot) = 0$ implies that $h=0$.  We deduce that $f=g$, concluding the proof.

We first show that $|v+w|\approx |v|+|w|$ for any $w \in (v-v')^{\perp}$.  The ``$\lesssim$'' inequality is clear, so we show the other inequality:
	\begin{align*}
	|v+w|^2
	&=
	|v|^2 +2v\cdot w +|w|^2
	=
	|v|^2 +2v'\cdot w +|w|^2
	\geq
	|v|^2 - \frac{1}{1-\theta}|v'|^{2}-(1-\theta) |w|^{2} +|w|^2
	\\&\geq
	|v|^2 - (1-\theta)|v|^{2}-(1-\theta) |w|^{2} +|w|^2



	=
		\theta |v|^2 + \theta|w|^2
	.
	\end{align*}
	In the second equality, we used that $(v-v')\cdot w = 0$, in the first inequality, we used Young's inequality, and in the second inequality, we used the hypothesis that $(1-\theta)|v| \geq |v'|$.


	Recalling~\eqref{e.carleman2} and changing variables, we have
	\[
		|v-v'|^{3+2s} K_g(v,v')
			\approx
				\int_{v+(v'-v)^{\perp}} g(w)|v-w|^{\gamma+2s+1} \,dw
			=
				\int_{(v'-v)^{\perp}} g(v+w)|w|^{\gamma+2s+1} \,dw.
	\]
	Clearly, it is enough to simply bound the integral on the right hand side.  Using that $|v+w|\approx |v| + |w|$, as established above, we see that
	\begin{equation}\label{e.c611}
	\begin{split}
	&\Big|\int_{(v'-v)^{\perp}}
	g(v+w)|w|^{\gamma+2s+1} \,dw\Big|
	\lesssim
		\|g\|_{L^{\infty,m}}
		\int_{(v'-v)^{\perp}}
	\frac{|v|^{\gamma + 2s + 1}}{\langle v+w \rangle^{m}} \,dw
	\\&\quad\lesssim
	\|g\|_{L^{\infty, m}}
	\int_{(v'-v)^{\perp}}
	\frac{|w|^{\gamma+2s+1}}{\langle v \rangle^{m}+\langle w \rangle^{m}} \,dw
	\\&\quad=
	\|g\|_{L^{\infty, m}}
	\int_{(v'-v)^{\perp}\cap B_{\langle v\rangle}}
	\frac{|w|^{\gamma+2s+1}}{\langle v \rangle^{m}+\langle w \rangle^{m}} \,dw
	+
	\|g\|_{L^{\infty, m}}
	\int_{(v'-v)^{\perp}\cap B^{c}_{\langle v\rangle}}
	\frac{|w|^{\gamma+2s+1}}{\langle v \rangle^{m}+\langle w \rangle^{m}} \,dw\\
	&\quad= \|g\|_{L^{\infty,m}} \left( I_1 + I_2\right).
	\end{split}
	\end{equation}

	For $I_1$, that is, $w \in B_{\langle v\rangle}$, we use the fact that
	\begin{equation}
		\frac{|w|^{\gamma+2s+1}}{\langle v \rangle^{m}+\langle w \rangle^{m}}
	\lesssim
		|w|^{\gamma + 2s + 1}
		\langle v \rangle^{-m}
	.												
	\end{equation}
	Thus, we see (recall we are integrating over a subset of a two-dimensional hyperplane)
	\begin{equation}\label{e.w05261}
	\begin{split}
	I_1
		\lesssim
			\langle v\rangle^{-m} \int_{(v'-v)^{\perp}\cap B_{\langle v\rangle}}
			|w|^{\gamma + 2s + 1} \,dw
		\lesssim
			\langle v \rangle^{\gamma +2s+3-m }
	.
	\end{split}
	\end{equation}


	For $I_2$, that is, $w \in B^{c}_{\langle v\rangle}$, we have
	\begin{align}
	\frac{|w|^{\gamma+2s+1}}{\langle v \rangle^{m}+\langle w \rangle^{m}}
	\lesssim	
	\frac{|w|^{\gamma+2s+1}}{\langle w \rangle^{m}}
	\lesssim		
	\langle w \rangle^{\gamma +2s+1-m }
	.			
	\end{align}
		Therefore, we get (again, recall, we are integrating over a subset of a two-dimensional hyperplane)
		\begin{equation}\label{e.w05262}
		\begin{split}
		I_2
		\lesssim
			\int_{(v'-v)^{\perp}\cap B^{c}_{\langle v\rangle}}
			\langle w \rangle^{\gamma +2s+1-m } \,dw
		\lesssim
			\langle v \rangle^{\gamma +2s+3-m }
		.
		\end{split}
		\end{equation}
	Combining~\eqref{e.c611}, \eqref{e.w05261}, and \eqref{e.w05262}, we obtain the desired inequality, concluding the proof.

\label{p03}
	For $\tilde s \in (0,1)$, $R>0$, $\ell \geq 0$, and $\mathcal{D} = \{(v,v') \in \mathbb{R}^6: |v-v'| \leq \langle v\rangle / R\}$, we have, for any $f \in H^{\tilde s, \ell}(\mathbb R^3)$,
	\begin{equation}\label{e.c353}
	\int_{\mathcal{D}}
	\langle v\rangle^{\ell} \frac{|f(v)-f(v')|^{2}}{|v-v'|^{3+2\tilde s}}\,dv'dv
	\lesssim
	\|f\|_{H^{\tilde s,\ell}}^2
	.
	\end{equation}

We prove this using the characterization of the $L^2$-norm via duality; that is, fix any $h \in L^2(\mathbb R^3)$ and we estimate
	\[
		\int h \left( \langle v\rangle^\ell Q_{\rm s}(g,f) - Q_{\rm s}(g,\langle v\rangle^\ell f)\right) \,dv.
	\]

	For any $v$, let $R_{v}=\langle v \rangle/10$ and denote the diagonal strip
	\begin{equation}\label{e.mcD}
		\mathcal D=\{(v,v'): |v-v'|<R_{v} \}.
	\end{equation}
	Recalling~\eqref{e.carleman1}, we rewrite the quantity of interest as
	\begin{equation}\label{e.c341}
	\begin{split}
		\int h &\left(\langle v \rangle^{\ell}Q_{\rm s}(g,f)- Q_{\rm s}(g, \langle v \rangle^{\ell}f) \right)\,dv


		=
		\int K_{g}(v,v')h(v) \left(\langle v \rangle^{l}f(v')- \langle v' \rangle^{l}f(v')  \right)\,dv'dv
		\\&=
		\int \limits_{\mathcal D} K_{g}(v,v')h(v) \left(\langle v \rangle^{\ell}f(v')- \langle v' \rangle^{\ell}f(v')  \right)\,dv'dv\\
 		&\qquad +
		\int\limits_{\mathcal D^c} K_{g}(v,v')h(v) \left(\langle v \rangle^{\ell}f(v')- \langle v' \rangle^{\ell}f(v')  \right)\,dv'dv
		=
		I_{1}+I_{2}.
	\end{split}
	\end{equation}
	We estimate each of $I_1$ and $I_2$ in turn. 

	\smallskip


	{\bf Step one: bounding $I_2$.}  We further decompose $I_2$ as
	\begin{equation}\label{e.c342}
	I_{2}
	=
	\int\limits_{\mathcal D^c} K_{g}(v,v')h(v) \langle v \rangle^{\ell}f(v')\,dv'dv
	-
	\int\limits_{\mathcal D^c} K_{g}(v,v')h(v) \langle v' \rangle^{\ell}f(v')\,dv'dv
	=
	I_{21}-I_{22}.
	\end{equation}

	We first consider $I_{22}$.  Applying \Cref{l:2.3}, we find
	\begin{equation}\label{e.c2241}
		\begin{split}
			|I_{22}|







			&\lesssim \|g\|_{L^{\infty, m}}
			\int\limits_{\mathcal D^c} \frac{|h(v)|}{|v-v'|^{3+2s}}
			\langle v \rangle^{\gamma+2s+1}
			\langle v' \rangle^{\ell}|f(v')|\,dv'dv
			.
		\end{split}
	\end{equation}
	Rewriting the limits of integration, using that $|v-v'| \gtrsim \langle v\rangle$, and applying Cauchy-Schwarz in $v'$ yields
	\[\begin{split}
	\int\limits_{\mathcal D^c} &\frac{|h(v)|}{|v-v'|^{3+2s}}
	\langle v \rangle^{\gamma+2s+1}
	\langle v' \rangle^{\ell}|f(v')|\,dv'dv
	= \int \langle v \rangle^{\gamma+2s+1} |h(v)|
	\left( \int_{B_{R_v}^c(v)} \frac{\langle v' \rangle^{\ell}|f(v')|}{|v-v'|^{3+2s}}
	dv' \right) dv\\
	&\lesssim \int \langle v \rangle^{\gamma-2} h(v)
	\left(\int
		\langle v'\rangle^{-3 - 2\epsilon} dv'\right)^{1/2}
	\left(\int \langle v' \rangle^	{\ell+3+2\epsilon}f^{2}(v') dv'\right)^{1/2}
	dv.
	\end{split}\]














	Noticing that the integral involving $f$ is a weighted $L^2$ norm of $f$, the middle integral is finite, and combining this with~\eqref{e.c2241}, we obtain
	\begin{equation}\label{e.w311}
		\begin{split}
			|I_{22}|




















			&\lesssim 
			\|g\|_{L^{\infty, m}}
			\|f\|_{L^{2, \ell+1}}
			\int\langle v \rangle^{\gamma - \frac{3}{2} }h(v) dv
			= \|g\|_{L^{\infty, m}}
			\|f\|_{L^{2, \ell+3/2+\epsilon}}
			\|h\|_{L^2}                                     
			.





		\end{split}
	\end{equation}
	We now consider $I_{21}$.  Here, we split the integral as follows:
	\begin{align*}
		I_{21}
		&=
		\int\limits_{\mathcal D^{c}\cap \{|v'|\geq |v|/10 \}} K_{g}(v,v')h(v) \langle v \rangle^{\ell}f(v')\,dv'dv
		+
		\int\limits_{\mathcal D^{c}\cap \{|v'|\leq |v|/10 \}} K_{g}(v,v')h(v) \langle v \rangle^{\ell}f(v')\,dv'dv\\
		&=
		I_{211}+I_{212}
		.
	\end{align*}
	The estimate of $I_{211}$ reduces to the estimate $I_{22}$:
	\begin{align*}
		|I_{211}|
		&\leq
		\int\limits_{\mathcal D^{c}\cap \{|v'|\geq |v|/10 \}} |K_{g}(v,v')h(v) \langle v \rangle^{\ell}f(v')|\,dv'dv
		\\&\lesssim
		\int\limits_{\mathcal D^{c}\cap \{|v'|\geq |v|/10 \}} |K_{g}(v,v')h(v) \langle v' \rangle^{\ell}f(v')|\,dv'dv
		\leq 
		\int\limits_{\mathcal D^{c}} |K_{g}(v,v')h(v) \langle v' \rangle^{\ell}f(v')|\,dv'dv.
	\end{align*}
	The last term above is exactly the term we estimate in~\eqref{e.c2241}; hence,
	\begin{equation}\label{e.w312}
		|I_{211}|
		\lesssim 
		\|g\|_{L^{\infty, m}}
		\|f\|_{L^{2, \ell+3/2+\epsilon}}
		\|h\|_{L^2}
		.
	\end{equation}
	Turning to $I_{212}$, we get
	\begin{equation}\label{e.c2251}
		\begin{split}
			|I_{212}| 



			&\lesssim		
			\|g\|_{L^{\infty, m}}
			\int\limits_{\mathcal D^{c}\cap \{|v'|\leq |v|/10 \}} \frac{h(v) \langle v \rangle^{\ell+\gamma +2s+3-m }f(v')}{|v-v'|^{3+2s}}\,dv'dv	.
		\end{split}
		\end{equation}
		After applying Cauchy-Schwarz to the integral in $v'$, a direct computation using that $\ell>3/2$ yields
		\begin{equation}\label{e.c2252}
		\begin{split}
			&\int\limits_{\mathcal D^{c}\cap \{|v'|\leq |v|/10 \}} \frac{h(v) \langle v \rangle^{\ell+\gamma +2s+3-m }f(v')}{|v-v'|^{3+2s}}\,dv'dv\\
			&\qquad\leq
			\int \langle v\rangle^{\ell + \gamma +2s+3-m}h(v)
			\left(\int_{B_{R_v}(v)^c \cap B_{|v|/10}} \frac{ \langle v'\rangle^{-2\ell} dv'}{|v-v'|^{6+4s}}\right)^{1/2}
			\left(\int \langle v'\rangle^{2\ell}f^{2}(v')\,dv'\right)^{1/2}
			dv
			\\&\qquad\lesssim
			\|f\|_{L^{2,\ell}}
			\int \langle v\rangle^{\ell + \gamma -m}h(v)
			dv.
		\end{split}
		\end{equation}
		Using that $m > \ell +\gamma+ \frac{3}{2}$, we conclude from~\eqref{e.c2251} and~\eqref{e.c2252} that
		\begin{equation}\label{e.w313}
		|I_{212}|
		\lesssim
		\|g\|_{L^{\infty, m}}
		\|f\|_{L^{2, \ell}}
		\|h\|_{L^{1, \ell + \gamma - m}}
		\lesssim
		\|g\|_{L^{\infty, m}}
		\|f\|_{L^{2, \ell}}
		\|h\|_{L^{2}}.
		\end{equation}
		Combining \eqref{e.w311}, \eqref{e.w312}, and \eqref{e.w313} we deduce that
		\begin{equation}\label{e.c311}
		|I_2|
		\lesssim \|f\|_{L^{2,\ell+1}} \|g\|_{L^{\infty,m}} \|h\|_{L^2}.
		\end{equation}
		This concludes step one.


		\smallskip


		{\bf Step two: bounding $I_1$.} 
		For notational convenience, let $W_\ell(v) = \langle v\rangle^\ell$.  For any function $\psi$ and any velocities $v$ and $v'$, let $\delta \psi= \psi(v) - \psi(v')$ (we suppress the dependence on $v$ and $v'$ as no confusion will arise).  Then, we rewrite $I_1$ as
		\begin{align*}
			I_{1}
			=
			\int \limits_{\mathcal D} K_{g}(v,v')h(v) \delta f\, \delta W_\ell\,dv'dv
			+
			\int \limits_{\mathcal D} K_{g}(v,v')h(v) f(v) \delta W_\ell\,dv'dv
			=
			I_{11}+I_{12}.
		\end{align*}
		For $I_{11}$, we see, by the definition of the kernel $K_{g}$ and get that
		\begin{equation}\label{e.c2253}
		I_{11}^2
		\lesssim \|g\|_{L^{\infty,m}}^2
		\left(\int \limits_{\mathcal D}  \frac{\langle v\rangle^{\gamma + 2s + 1}}{|v-v'|^{3 + 2s}} |h(v)| |\delta f| |\delta W_\ell|\,dv'dv\right)^{2}.
		\end{equation}
		Next,                                           
		applying the Cauchy-Schwarz inequality yields
		\begin{equation}\label{e.c2254}
		\begin{split}
			&\left(\int \limits_{\mathcal D}  \frac{\langle v\rangle^{\gamma + 2s + 1}}{|v-v'|^{3+2s}} |h(v)| |\delta f| |\delta W_\ell|\,dv'dv\right)^{2}\\
			&\quad \leq
			\left(\int \limits_{\mathcal D}  \frac{h(v)^2}{\langle v\rangle^{2\mu}} |v-v'|^{-3+2\mu}\,dv'dv\right)
			\left(\int \limits_{\mathcal D} \langle v\rangle^{2(\mu+\gamma + 2s + 1)} \frac{(\delta f)^2 (\delta W_\ell)^2}{|v-v'|^{3 + 4s +2\mu}} \,dv'dv\right).
		\end{split}
		\end{equation}
		We first consider the integral involving $h$.  Recalling the definition of $\mathcal{D}$~\eqref{e.mcD}, we find
		\begin{equation}\label{e.c2255}
		\begin{split}
			\int \limits_{\mathcal D}  h(v)^{2}|v-v'|^{-3 + 2\mu}\langle v\rangle^{-2\mu}\,dv'dv
			&\leq \int h(v)^2 \langle v\rangle^{-2\mu} \int_{B_{R_v}(v)} |v-v'|^{-3 + 2\mu} dv' dv\\
			&\lesssim \int h(v)^2 dv
			= \|h\|_{L^2}^2.
		\end{split}
		\end{equation}
		Next, we consider the second integral in~\eqref{e.c2254}.  
		Recall that $|v-v'|<R_{v}$ by the definition of $\mathcal{D}$,~\eqref{e.mcD}.  Hence, by Taylor's theorem, we have
		\[
		|\delta W_\ell|^2
		\lesssim
		|v'-v|^{2}\langle v \rangle^{2\ell-2}.
		\]
		Using this and \Cref{p03}, we find
		\begin{equation}\label{e.c2256}
		\begin{split}
			\int \limits_{\mathcal D}
			\frac{\langle v\rangle^{2(\mu + \gamma + 2s + 1)}(\delta f)^{2} (\delta W_\ell)^{2}}
			{|v-v'|^{3 + 4s + 2\mu}} \,dv'dv
			&\lesssim 
			\int \limits_{\mathcal D}
			\frac{\langle v\rangle^{2(\mu + \gamma + 2s + \ell)}(\delta f)^2}{|v-v'|^{3 + 2(2s - 1 + \mu)}}\,dv'dv
			\lesssim \|f\|_{H^{2s-1 + \mu, \mu + \ell}}^2.
		\end{split}
		\end{equation}





		We conclude by combining~\eqref{e.c2253}-\eqref{e.c2256} to obtain
		\begin{equation}\label{e.w314}
		|I_{11}|
		\lesssim \|g\|_{L^{\infty,m}} \|h\|_{L^2} \|f\|_{H^{2s  - 1 + \mu, \mu + \ell+\gamma+2s}}
		\end{equation}












		We consider now $I_{12}$.  Using a second order Taylor expansion of $W_\ell(v) =\langle v\rangle^\ell$, we see that
		\begin{align*}
			I_{12}
			&=
			\int \limits_{\mathcal D} K_{g}(v,v')h(v) f(v) \delta W_\ell\,dv'dv	
			\\&=
			\int h(v) f(v)\int \limits_{B_{R_{v}(v)}}  K_{g}(v,v')\left((D_{v} W_\ell)|_v (v-v')
			+\frac{1}{2} (v-v')\cdot (D_{v}^{2} W_\ell)|_{\xi_{v,v'}} (v-v')\right)\,dv'dv






			\\&=
			I_{121} + I_{122},
		\end{align*}
		where $\xi_{v,v'} = tv' + (1-t)v$ for some $t \in [0,1]$.
		For $I_{121}$, we use \Cref{p.w3311}.\eqref{l.is3.7} to obtain                                                                                 






		\begin{equation}\label{e.c351}
		I_{121}=0.
		\end{equation}
		For $I_{122}$, we use that $|(D^2_v W_\ell)|_{\xi_{v,v'}}| \lesssim \langle v\rangle^{\ell-2}$, due to the fact that $v' \in B_{R_v}(v)$, in order to find
		\[
		|I_{122}|








		\lesssim
		\int_{\mathbb R^3} |h(v) f(v)|\int_{B_{R_{v}(v)}}  |K_{g}(v,v')|
		\langle v\rangle^{\ell-2} |v-v'|^2\,dv'dv.
		\]
		Thus, we have by appealing to \Cref{l:new kernel}
		\begin{equation}\label{e.w315}
			\begin{split}
				|I_{122}|
				&\lesssim
				\|g\|_{L^{\infty,m}}
				\int_{\mathbb R^3} |h(v) f(v)|  
				\langle v\rangle^{\ell-2 + \gamma + 2s} \,dv
				\lesssim
				\|g\|_{L^{\infty,m}}
				\|f\|_{L^{2, \ell-2 + \gamma + 2s}}
				\|h\|_{L^{2}}.
			\end{split}
		\end{equation}
		Combining~\eqref{e.c351} and~\eqref{e.w315} and the fact that $\ell+3/2+\epsilon > \ell-2+\gamma + 2s$, we find
		\begin{equation}\label{e.c352}
		|I_{12}|
		\lesssim \|g\|_{L^{\infty,m}}
		\|f\|_{L^{2, \ell+1}}
		\|h\|_{L^{2}}.
		\end{equation}
		Thus, by~\eqref{e.w314} and \eqref{e.c352},
		\[
		|I_1|
		\lesssim \left(\|f\|_{L^{2,\ell+3/2+\epsilon}}+\|f\|_{H^{2s-1+\mu,\mu + \ell+\gamma+2s}}\right)
		\|g\|_{L^{\infty,m}}
		\|h\|_{L^2}.
		\]
		This concludes step two, and, thus, the proof.

We adopt the notation and setting of the proof of \Cref{p:thm_2.4}.(i).  Then
\[
	\begin{split}
		\frac{1}{\|g\|^{1/2}_{L^{\infty,3+\gamma+2s+\epsilon}}} \|Q_{\rm s}(g,f)\|_{L^2}
			&= \|\hat L_g f\|_{L^2}
			\leq \sum_{i=0}^\infty \|\hat L_g \Delta_i f\|_{L^2}
			\lesssim \sum_{i=0}^\infty 2^{-i\theta} \|\Delta_i f\|_{H^{2s+\theta}}\\
			&\lesssim \Big(\sum_{i=0}^\infty \|\Delta_i f\|^2_{H^{2s+\theta}}\Big)^{1/2}
			\approx \|f\|_{H^{2s+\theta}}.
	\end{split}
\]

\label{l: Weighted Young}
	Suppose that $n > 3/2 + \eta$, $-3<\eta<0$, and $\ell > 3/2 + \eta + (3/2 - n)_+$.  If $g \in L^{2,n}$, then











	\begin{equation}
	\int \langle v\rangle^{-2\ell}\left(\int g(\tilde v)|v-\tilde v|^{\eta}\,d\tilde v \right)^{2}\,dv
	\lesssim
	\|g\|_{L^{2,n}}^2
	.
	\end{equation}

\label{l:w0513}





	For any measurable $g$, if $\gamma + 2s \leq 0$ and $\epsilon>0$, then
	\begin{equation}
		\begin{split}
			\Big|\int K_{g}(f'-f)^{2}\,dv'dv\Big|
			\lesssim
			\|g\|_{L^{\infty, 3+\gamma + 2s + \epsilon}}
			\|f\|_{H^s}^{2}
			.
		\end{split}
	\end{equation}

We consider only the case $\partial=\partial_{v_i}$ for $i \in \{1,2,3\}$. The case when $\partial=\partial_{x_i}$ is similar and simpler as it commutes with $\langle v\rangle^{2n}$.                                                                                                                                   
	First, let $F=\langle v\rangle^{n}f$. Then                                                                          
	\begin{equation*}
		\begin{split}
			\int \langle v\rangle^{2n}Q_{\rm s}(g,f)\partial f\,dvdx
			&=
			\int [\langle v\rangle^{n}Q_{\rm s}(g,f)-Q_{\rm s}(g,\langle v\rangle^{n}f)]\langle v\rangle^{n}\partial f\,dvdx
			-
			\int Q_{\rm s}(g,F)fnv_{i}\langle v\rangle^{n-2}\,dvdx
			\\&\quad+
			\int Q_{\rm s}(g,F)\partial F\,dvdx
			=
			I_{1}+I_{2}+I_{3}
			.
		\end{split}
	\end{equation*}
	For $I_{1}$, we apply the commutator estimate \Cref{p:commutator} to get
	\begin{equation}
		\begin{split}\label{e.w04111}
			|I_{1}|
			&\lesssim
			\int
			(\|f\|_{L_v^{2,n+3/2 + \epsilon}} + \|f\|_{H_v^{2s -1 + \mu,\mu+ n + \gamma + 2s}})
			\|g\|_{L_v^{\infty, m}}
			\|\partial f\|_{L_v^{2,n}}
			\,dx
			\\&\lesssim
			\int
			(\|f\|_{L_v^{2,n+3/2 + \epsilon}} + \|f\|_{H_v^{2s -1 + \mu,\mu+ n + \gamma + 2s}})
			\|g\|_{L_v^{\infty, m}}
			\|f\|_{H_v^{1,n}}
			\,dx
			\\&\lesssim
			\|g\|_{L^{\infty, m}}
			\left(
			\|f\|_{L^{2,n + 3/2 + \epsilon}}
			+
			\|f\|_{H^{2s -1 + \mu,\mu+n + \gamma + 2s}}
			\right)
			\|f\|_{H^{1,n}}.









		\end{split}
	\end{equation}

	To estimate $I_{2}$, we apply \Cref{p:thm_2.4}.(i) with $\theta=1$ if $s > 1/2$ or $\theta = 2s-1+\mu$ if $s \leq 1/2$ to find
	\begin{equation}\label{e.w04112}
	\begin{split}
	|I_{2}|
	&\lesssim
	\int
	\|g\|_{L_v^{\infty, m}}  \|F\|_{H_v^{\theta}}\|fnv_{i}\langle v\rangle^{n-2}\|_{H_v^{2s-\theta}}
	\,dx
	\\&\lesssim
	\int
	\|g\|_{L_v^{\infty, m}}  \|f\|_{H_v^{\theta,n}}\|f\|_{H_v^{2s-\theta, n-1}}
	\,dx
	\lesssim \|g\|_{L^{\infty, m}}  \|f\|_{H^{\theta,n}}\|f\|_{H^{2s-\theta, n-1}}.
	\end{split}
	\end{equation}
	Using the choice of $\theta$, the right hand side above is less than or equal to (up to a constant) the right hand side of~\eqref{e.w04111}.                 




























	We decompose $I_3$ into two parts:
	\[
		\begin{split}
			I_{3}
			&=
			\int Q_{\rm s}(g,F)\partial F\,dv dx\\
			&=
			\int K_{g}(F'-F)(\partial F - (\partial F)')\,dv'dv dx
			+
			\int (K_{g}-K'_{g})(F'-F)\partial F\,dv'dv dx
			=
			I_{31}+I_{32}
			.
		\end{split}
	\]
	For $I_{31}$, we manipulate by integration-by-parts and apply \Cref{l:w0513} to find
\[
		\begin{split}
			|I_{31}|
			&=
			\Big|\int K_{g}(\partial+\partial')(F'-F)^{2}\,dv'dv dx\Big|
			=
			\Big|\int (\partial+\partial')K_{g}(F'-F)^{2}\,dv'dv dx\Big|
			\\&=
			\Big|\int K_{\partial g}(F'-F)^{2}\,dv'dvdx\Big|
			\lesssim
			\int \|\partial g\|_{L_v^{\infty, 3+\gamma + 2s + \epsilon}}
			\|F\|_{H_v^s}^{2} dx
			=
			\int \|\partial g\|_{L_v^{\infty, 3+\gamma + 2s + \epsilon}}
			\|f\|_{H_v^{s,n}}^{2} dx


			.
		\end{split}
\]

















	Fix the conjugate exponents $p=3/2(1-s)$ and $q=3/(2s+1)$.  Applying H\"older's inequality and the Sobolev embedding theorem yields
	\[
	\begin{split}
	|I_{31}|

	&\lesssim 
	\|\partial g\|_{L^p_x L_v^{\infty,3+\gamma + 2s + \epsilon}} \|f\|_{L^{2q}_x H_v^{s,n}}^2\\
	&\lesssim 
	\|\partial g\|_{H^{(2s - 1/2)_+}_x H_v^{3/2+\epsilon,3+\gamma + 2s + \epsilon}} \|f\|_{H^{1-s}_x H_v^{s,n}}^2
	\lesssim 
	\|\partial g\|_{H^{3/2 + \epsilon + (2s-1/2)_+,3+\gamma + 2s + \epsilon}} \|f\|_{H^{1,n}}^2.
	\end{split}
	\]







The term $I_{32}$ is considered in \cite[Proposition 3.1.(iv), estimate of $I_2$]{HST_boltz_wp}.  A close inspection of the proof shows that it applies in our setting.  Hence, for simplicity, we cite directly that, for any $\mu \in (s,\min\{2s,1\})$,
	\begin{align*}\label{e.w04092}
		|I_{32}|

		\lesssim
		\| g\|_{C^{\mu, 3+\epsilon}}
		\|f\|_{H^{s,n + 3/2 + \epsilon + (\gamma + 2s + 1)_+}}
		\|f\|_{H^{1, n}}
		.
	\end{align*}
	Combining the above estimates of $I_{31}$ and $I_{32}$ together yields
	\begin{equation}\label{e.w04093}
		\begin{split}
			|I_{3}|
			\lesssim
			\|\partial g\|_{H^{3-s,3}} \|f\|_{H^{1,n}}^2
			+
			\| g\|_{C^{\mu, 3+\epsilon}}
			\|f\|_{H^{s,n + 3/2 + \epsilon + (\gamma + 2s + 1)_+}}
			\|f\|_{H^{1, n}}
			.
		\end{split}
	\end{equation}

	The proof is finished after combining~\eqref{e.w04111}, ~\eqref{e.w04112}, and~\eqref{e.w04093}.

\label{l:Qs_C1}
Let $m_1 > 3+ \gamma + 2s$ and $m_0$ sufficiently large depending only on $m_1$, $s$, and $\gamma$. The following inequality holds
\[
	\|Q_{\rm s}(g,f)\|_{L^{\infty,m_{1}}}
	\lesssim
	\|g\|_{L^{\infty,m_{1}}}
		\left(
			\|f\|_{L^{\infty,m_{0}}}
			+
			\|\nabla_{v}f\|_{L^{\infty,m_{1}}}
		\right).
\]

Let $\mu = 1$ if $\gamma \leq -1$ and $\mu = \frac{-\gamma - 2s}{1-2s}$ otherwise.  Fix $r = \langle v\rangle^\mu/2$.  We first decompose the integral into two parts:                                                                        
\[
	|Q_{{\rm s}}(g,f)\langle v\rangle^{m_{1}}|
	=
	\int \left|\langle v\rangle^{m_1}(f(v') - f(v)) K_g(v,v')\right| dv'
	\leq I_1 + I_2,
\]
		where $I_1$ and $I_2$ are the integrals over $B_r(v)$             
		and $B_r(v)^c$, respectively.
Applying \Cref{l:new kernel} and using that if $\xi \in B_r(v)$ then $\langle \xi\rangle \approx \langle v\rangle$, we bound $I_1$ as
\begin{equation}\label{e.c681}
	\begin{split}
		I_1



		&\lesssim
		      \|\nabla_{v}f\|_{L^{\infty,m_1}}
		\int_{ B_{r}(v)}  |v-v'| K_{|g|}(v,v') dv'
		\lesssim
			\|\nabla_{v}f\|_{L^{\infty,m_1}}
			r^{1-2s} \int |g(w)||v-w|^{\gamma + 2s} dw.
















	\end{split}
\end{equation}
We are finished after bounding the integral by $\langle v\rangle^{\gamma + 2s} \|g\|_{L^{\infty, m_0}}$ and using the definition of $r$.


The first step to handle $I_2$ is to split it into the parts containing $f(v)$ and $f(v')$ via the triangle inequality.  Call these integrals $I_{21}$ and $I_{22}$, respectively.  Using \Cref{l.is3.4} again, we see that
\[
	\begin{split}
		I_{21}
			= \int_{B_r(v)^c} \langle v\rangle^{m_1} |f(v)| K_{|g|}(v,v') dv'
			\lesssim \|f\|_{L^{\infty,m_0}} \langle v\rangle^{-m_0} r^{-2s} \int g(z) |v-z|^{\gamma + 2s} dv'.
	\end{split}
\]
Bounding the last integral using $\|g\|_{L^{\infty,m_1}}$ and using the definition of $r$ finishes the estimate of $I_{21}$.


The last integral, that of $I_{22}$ requires further decomposition into $I_{221}$ and $I_{222}$ over the domains $B_r(v)^c \cap B_{\langle v\rangle/2}^c$ and $B_r(v)^c \cap B_{\langle v\rangle/2}$.  The former is easy to handle using
	\[
		|f(v')|
			\leq \|f\|_{L^{\infty,m_0}} \langle v'\rangle^{-m_0}
			\lesssim \|f\|_{L^{\infty,m_0}} \langle v\rangle^{-m_0}

	\]
	where we used that $\langle v'\rangle \gtrsim \langle v\rangle$.  The rest of the bound follows exactly as for $I_{21}$.

	As for $I_{222}$, notice that for such $v'$, $|v-v'| \approx \langle v\rangle$.  We use this, along with \Cref{l: w0524}, to find
\begin{equation}\label{e.c682}
	\begin{split}
		I_{222}

			&\lesssim \|g\|_{L^{\infty,m_1}} \int_{B_r(v)^c \cap B_{\langle v\rangle/2}} \frac{\langle v\rangle^{m_1} f(v')}{\langle v\rangle^{3+2s}}  \langle v\rangle^{3+\gamma+2s-m_1} dv'\\
			&\lesssim \|g\|_{L^{\infty,m_1}} \int_{B_r(v)^c \cap B_{\langle v\rangle/2}} \langle v\rangle^\gamma f(v') dv'
			\lesssim \|g\|_{L^{\infty,m_1}} \|f\|_{L^{\infty,m_0}}.
	\end{split}
\end{equation}
Combining this with the above estimates finishes the proof.

\label{l03}
	Fix any $m_1 > 3 + \gamma + 2s$ and $m_0$ sufficiently large depending only on $m_1$, $\gamma$ and $s$.  Suppose that $f_{\rm in} \in \tilde X^{m_0,m_1}$, and $g, R \in \tilde Y^{m_0,m_1}_T$.  If $f$ solves~\eqref{e.w316} then, there is a constant $C>0$ depending only on $m$, $s$, and $\gamma$ such that
	\[
		\|f\|_{\tilde Y^{m_0,m_1}}
			\lesssim \exp\Big\{C\int_{0}^{T} \|g(t)\|_{\tilde X^{m_0,m_1}}dt\Big\}
				\left( \|f_{\rm in}\|_{\tilde X^{m_0,m_1}}
					+ T \|R\|_{\tilde Y_T^{m_0,m_1}}\right).
	\]

First notice that the proof of the bound
	\begin{equation}\label{e.c683}
		\|f\|_{L^\infty([0,T];L^{\infty,m_0})}
			\lesssim e^{C \int_0^T\|g(t)\|_{L^{\infty,m_0}} dt } \Big(\|f_{\rm in}\|_{\tilde X^{m_0,m_1}}
					+ \int_0^T \|R(t)\|_{ \tilde X^{m_0,m_1}} dt\Big).
	\end{equation}
	is exactly the same as the (brief) proof in \cite[Proposition~3.1]{HST_boltz_wp} and, hence, is omitted here.  We note that it is a simpler version of the proof of the bounds on the derivatives that follows.

We now focus instead on bounding $\nabla_{x,v}f$.  Fix $\phi(t)$ to be an increasing function to be determined such that $\phi(0) = \|\nabla_{x,v}f_{\rm in}\|_{L^{\infty,m_1}}$, and let $F(t,x,v) = \phi(t) \langle v\rangle^{-m_1}$.  Clearly we have that
\begin{equation}\label{e.c651}
	F(0,x,v) > \max\left\{|\partial_{x_i} f_{\rm in}(x,v)|, |\partial_{v_i}f(x,v)| : i \in \{1,2,3\}\right\}
		\quad\text{ for all } (x,v).
\end{equation}
Let $t_0$ be the first time that the above inequality is violated.  If $t_0$ does not exist, we are finished.  Hence, we argue by contradiction assuming that there exists $t_0 \in [0,T]$.  Without loss of generality\footnote{Indeed, the only technical issue here is if the inequality is violated at $|v|=\infty$.  One may sidestep this by simply including a cutoff as a multiplicative factor of the initial data and of $R$.  It then follows from standard facts about the heat equation that $f$ and its derivatives decay as a Gaussian at high velocities.  The cutoff can be removed by a limiting procedure.}, we may assume that there exists $(x_0,v_0) \in \mathbb T^3 \times \mathbb R^3$ such that equality above holds in~\eqref{e.c651} at the point $(t_0,x_0,v_0)$.  Assume momentarily that
\begin{equation}
	F(t_0,x_0,v_0)
		= \partial_{x_1} f(t_0,x_0,v_0).
\end{equation}
The cases where $i = 2,3$ are clearly analogous, as are the case when a negative sign appears in the equality (i.e., $F = - \partial_{x_1} f$).  The case when the derivative is in the $v$ variable is slightly more complicated as new terms arise, but these new terms can be handled in a straightforward way.

Since $F - \partial_{x_1} f \geq 0$ on $[0,t_0]\times\mathbb T^3\times\mathbb R^3$, we find
\begin{equation}\label{e.c652}
	0
		\geq \partial_t (F - \partial_{x_1} f)
			+ v\cdot \nabla_x(F - \partial_{x_1} f)
			- (\epsilon + (1-\sigma)) \Delta_{x,v} (F - \partial_{x_1} f)
			- \sigma Q_{\epsilon,\delta}(g, F - \partial_{x_1} f).
\end{equation}
We use this to derive a contradiction.

On the one hand, an explicit computation for $F$, along with \cite[Proposition 3.1.(v)]{HST_boltz_wp} yields
\begin{equation}\label{e.c653}
	\partial_t F + v\cdot\nabla_x F - (\epsilon + (1-\sigma)) \Delta_{x,v} F - \sigma Q_{\epsilon, \delta}(g,F)
		\geq \phi' \langle v_0\rangle^{-m_1}
			- C\phi (1 + \|g\|_{L^{\infty,m_1}}) \langle v_0\rangle^{-m_1},
\end{equation}
where we used that $m_1 > 3 + \gamma + 2s$, a condition of the quoted result.

On the other hand, using \Cref{l:Qs_C1}, we find
\begin{equation}\label{e.c654}
	\begin{split}
		\partial_t \partial_{x_1} f
			&+ v\cdot\nabla_x\partial_{x_1} f
			- (\epsilon + (1-\sigma)) \Delta_{x,v} \partial_{x_1} f 
			- \sigma Q_{\epsilon, \delta}(g,\partial_{x_1} f)
			= \sigma Q_{\epsilon, \delta}(\partial_{x_1} g, f) + \partial_{x_1}R
			\\& \lesssim \left(\|g(t_0)\|_{\tilde X^{m_0,m_1}} \left( \|f\|_{L^{\infty, m_0}} + \|\nabla f\|_{L^{\infty,m_1}}\right)
				+ \|R(t_0)\|_{\tilde X^{m_0,m_1}}\right) \langle v_0\rangle^{-m_1}\\
			&\leq \left(\|g(t_0)\|_{\tilde X^{m_0,m_1}} \left( \|f\|_{L^{\infty, m_0}} + \phi\right)
				+ \|R(t_0)\|_{\tilde X^{m_0,m_1}}\right) \langle v_0\rangle^{-m_1}.
	\end{split}
\end{equation}
Using~\eqref{e.c683}, it is clear from~\eqref{e.c653} and~\eqref{e.c654} that we can choose $\phi$ to obtain a contradiction in~\eqref{e.c652}.  This yields a contradiction.  Hence~\eqref{e.c651} always holds, finishing the proof.
